import random

def girth(graph, n):
    """Compute girth of graph. If no cycles, return infinity."""
    from collections import deque

    min_cycle = float('inf')

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent[v] != u:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle if min_cycle != float('inf') else float('inf')

def is_4_colorable(graph, n):
    """Check if graph is 4-colorable using backtracking."""
    colors = [-1] * n

    def can_color(v):
        if v == n:
            return True

        # Try colors 0, 1, 2, 3
        for c in range(4):
            ok = True
            for u in graph[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if can_color(v + 1):
                    return True
                colors[v] = -1
        return False

    return can_color(0)

